export const descriptions={6654:"Самурай покупает новый меч и решает испытать его на прохожих. Короткая комедия 1917 года — один из ранних сохранившихся образцов японской анимации.",52991:'После победы над королём демонов Фрирен остаётся жить намного дольше своих спутников. Новое путешествие помогает ей понять людей и ценность времени, проведённого вместе.',5114:'Братья Элрик ищут способ вернуть утраченные тела. Их путь к философскому камню становится расследованием тайны целой страны.',9253:'Необычный эксперимент позволяет отправлять сообщения в прошлое. Но каждое изменение времени имеет последствия.',11061:'Гон отправляется на экзамен охотников, чтобы пойти по следам отца. Впереди — друзья, испытания и мир, намного сложнее его ожиданий.',16498:'Последние человеческие города окружены стенами. Когда одна из них падает, Эрен решает противостоять титанам.',38000:'Тандзиро становится охотником на демонов и ищет способ вернуть человеческий облик своей сестре.',32281:'Школьник из Токио и девушка из провинции начинают просыпаться в телах друг друга. За этой странной связью скрывается нечто большее.',21:'Луффи собирает команду и отправляется в море на поиски легендарного сокровища Ван-Пис.',1535:'В руках школьника оказывается тетрадь, способная убивать по имени. Его представления о справедливости сталкиваются с расследованием загадочного детектива.',1:'Команда охотников за головами путешествует по Солнечной системе. За каждой новой работой проступают истории их прошлого.',199:'Тихиро попадает в мир духов и устраивается работать в необычной купальне, чтобы спасти родителей.',40861:'Семь коротких историй о мечтах и повседневной жизни жителей Галара. Молодой поклонник покемонов, лидеры стадионов и чемпион Леон оказываются связаны одним путешествием.'};
export function titleOf(a){return ruTitles[a.id]||a.title;}
export function normalize(s){return String(s??'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replaceAll('ё','е');}
export function filterCatalog(data,{q='',genre='',type='',year='',sort='',watch=false}={},streams={}){
 const terms=normalize(q).trim().split(/\s+/).filter(Boolean);
 const result=data.filter(a=> (!watch||streams[a.id]?.length)&&(!genre||a.genres.includes(genre))&&(!type||a.type===type)&&(!year||String(a.year)===year)&&terms.every(t=>normalize([titleOf(a),a.title,...a.aliases].join(' ')).includes(t)));
 if(sort==='score')result.sort((a,b)=>b.score-a.score||a.id-b.id);
 if(sort==='year')result.sort((a,b)=>(b.year||0)-(a.year||0)||b.score-a.score);
 if(sort==='title')result.sort((a,b)=>titleOf(a).localeCompare(titleOf(b),'ru'));
 return result;
}
export function safeUrl(value,hosts){try{const u=new URL(value);return u.protocol==='https:'&&hosts.includes(u.hostname)?u.href:'';}catch{return '';}}
export function videoUrl(id){return /^[\w-]{11}$/.test(id)?`https://www.youtube-nocookie.com/embed/${id}`:'';}
export function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
